card.content:
{
  "conclusion": "建议周六（9月9日）凌晨前往上海郊外光污染较低处拍摄银河，新月月光干扰低，云量少，需携带广角大光圈镜头、三脚架和快门线。",
  "evidence": [
    {
      "tool": "weather_forecast",
      "field": "每日预报",
      "confidence": "high",
      "note": "9月9日平均云量18%，为周末最低，适合拍摄"
    },
    {
      "tool": "moon_phase",
      "field": "月相名称",
      "confidence": "high",
      "note": "新月，照亮比例2%，月光影响低，银河可见性好"
    },
    {
      "tool": "sun_times",
      "field": "日落",
      "confidence": "medium",
      "note": "日落18:06，银河拍摄需在日落后约2小时开始"
    }
  ],
  "confidence": "high",
  "time_window": "2026-09-09 凌晨 00:00 - 04:00（最佳）",
  "locations": [
    {
      "name": "默认机位（上海）",
      "reason": "虽为城市，但可尝试郊外光污染较低处；若无法离开，可寻找公园或高地"
    }
  ],
  "params": [
    {
      "name": "镜头焦距",
      "value": "14-24mm",
      "reason": "广角镜头可纳入更多银河细节"
    },
    {
      "name": "光圈",
      "value": "f/2.8 或更大",
      "reason": "大光圈增加进光量，提高银河亮度"
    },
    {
      "name": "ISO",
      "value": "3200-6400",
      "reason": "根据相机性能调整，平衡噪点与亮度"
    },
    {
      "name": "快门速度",
      "value": "15-20秒",
      "reason": "使用500法则：500/焦距≈快门上限，避免星轨"
    }
  ],
  "alternatives": [
    "若周六云量变化，可改周日（9月10日）凌晨，但云量55%需谨慎",
    "若无法离开城市，可尝试拍摄星轨或城市夜景代替"
  ],
  "degraded": ""
}
